True def transform(grid):
    line = grid[0]
    n = len(line)
    center = line.index(2)
    out = [[0] * n for _ in range(n)]
    for r in range(n):
        lo, hi = max(0, center - r), min(n - 1, center + r)
        for c in range(lo, hi + 1):
            if c == center - r or c == center + r:
                out[r][c] = 2
            elif (c - center - r) % 4 == 0:
                out[r][c] = 1
    return out
